# Deterministic independent-cascade special case, with shared descendants.
weights = {'a':10, 'b':8, 'z':-9, 'c':0.5}
edges = {'a':['z'], 'b':['z'], 'z':[], 'c':[]}
def sigma(seeds):
    reached=set(seeds)
    pending=list(seeds)
    while pending:
        for v in edges[pending.pop()]:
            if v not in reached:
                reached.add(v)
                pending.append(v)
    return sum(weights[v] for v in reached)
print('Signed-weight lazy greedy example:')
print('Singletons:', {v: sigma({v}) for v in weights})
print('After selecting a, actual marginals:', {v: sigma({'a',v})-sigma({'a'}) for v in weights if v"'!='"'a'})
print('Greedy value:',sigma({'a','b'}),'CELF using stale upper bounds:',sigma({'a','c'}))
